window.ScripturaLexicons.BDAG_PART_0211 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0211-01\" data-source=\"BDAG\" data-search=\"κριτικός, ή, όν adjetivo capaz de discernir ou julgar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κριτικός, ή, όν</td><td>adjetivo</td><td>capaz de discernir ou julgar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0211-02\" data-source=\"BDAG\" data-search=\"Κρόκος, ου, ὁ nome próprio masculino Croco; cristão de Éfeso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κρόκος, ου, ὁ</td><td>nome próprio masculino</td><td>Croco; cristão de Éfeso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0211-03\" data-source=\"BDAG\" data-search=\"κροκώδης, ες adjetivo amarelo-açafrão; cor de açafrão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κροκώδης, ες</td><td>adjetivo</td><td>amarelo-açafrão; cor de açafrão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0211-04\" data-source=\"BDAG\" data-search=\"κρούω verbo bater; dar pancadas; bater à porta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κρούω</td><td>verbo</td><td>bater; dar pancadas; bater à porta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0211-05\" data-source=\"BDAG\" data-search=\"κρύβω verbo; remissão veja κρύπτω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κρύβω</td><td>verbo; remissão</td><td>veja κρύπτω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0211-06\" data-source=\"BDAG\" data-search=\"κρύπτη, ης, ἡ substantivo feminino esconderijo; lugar oculto; porão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κρύπτη, ης, ἡ</td><td>substantivo feminino</td><td>esconderijo; lugar oculto; porão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0211-07\" data-source=\"BDAG\" data-search=\"κρυπτός, ή, όν adjetivo e substantivo oculto; secreto; aquilo que está escondido BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κρυπτός, ή, όν</td><td>adjetivo e substantivo</td><td>oculto; secreto; aquilo que está escondido</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0211-08\" data-source=\"BDAG\" data-search=\"κρύπτω verbo esconder; ocultar; encobrir; manter secreto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κρύπτω</td><td>verbo</td><td>esconder; ocultar; encobrir; manter secreto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0211-09\" data-source=\"BDAG\" data-search=\"κρυσταλλίζω verbo brilhar como cristal; ser transparente como cristal BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κρυσταλλίζω</td><td>verbo</td><td>brilhar como cristal; ser transparente como cristal</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0211-10\" data-source=\"BDAG\" data-search=\"κρύσταλλος, ου, ὁ substantivo masculino cristal de rocha; possivelmente gelo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κρύσταλλος, ου, ὁ</td><td>substantivo masculino</td><td>cristal de rocha; possivelmente gelo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0211-11\" data-source=\"BDAG\" data-search=\"κρυφαῖος, αία, αῖον adjetivo oculto; secreto; reservado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κρυφαῖος, αία, αῖον</td><td>adjetivo</td><td>oculto; secreto; reservado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0211-12\" data-source=\"BDAG\" data-search=\"κρυφῇ advérbio em segredo; secretamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κρυφῇ</td><td>advérbio</td><td>em segredo; secretamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0211-13\" data-source=\"BDAG\" data-search=\"κρύφιος, ία, ιον adjetivo oculto; secreto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κρύφιος, ία, ιον</td><td>adjetivo</td><td>oculto; secreto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0211-14\" data-source=\"BDAG\" data-search=\"κτάομαι verbo médio adquirir; obter; granjear; trazer sobre si; possuir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κτάομαι</td><td>verbo médio</td><td>adquirir; obter; granjear; trazer sobre si; possuir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0211-15\" data-source=\"BDAG\" data-search=\"κτῆμα, ατος, τό substantivo neutro bem adquirido; propriedade; terreno BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κτῆμα, ατος, τό</td><td>substantivo neutro</td><td>bem adquirido; propriedade; terreno</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0211-16\" data-source=\"BDAG\" data-search=\"κτῆνος, ους, τό substantivo neutro animal doméstico; gado; animal de carga ou montaria BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κτῆνος, ους, τό</td><td>substantivo neutro</td><td>animal doméstico; gado; animal de carga ou montaria</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0211-17\" data-source=\"BDAG\" data-search=\"κτήτωρ, ορος, ὁ substantivo masculino proprietário; possuidor de terras e casas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κτήτωρ, ορος, ὁ</td><td>substantivo masculino</td><td>proprietário; possuidor de terras e casas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0211-18\" data-source=\"BDAG\" data-search=\"κτίζω verbo criar; trazer à existência; formar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κτίζω</td><td>verbo</td><td>criar; trazer à existência; formar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0211-19\" data-source=\"BDAG\" data-search=\"κτίσις, εως, ἡ substantivo feminino ato de criar; criatura; criação; sistema instituído de autoridade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κτίσις, εως, ἡ</td><td>substantivo feminino</td><td>ato de criar; criatura; criação; sistema instituído de autoridade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0211-20\" data-source=\"BDAG\" data-search=\"κτίσμα, ατος, τό substantivo neutro criatura; coisa criada por Deus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κτίσμα, ατος, τό</td><td>substantivo neutro</td><td>criatura; coisa criada por Deus</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0211-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κριτικός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κριτικός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (veja <span class=\"greek\">κρίνω</span>; Pla. e outros; Strabo, Plut., Lucian e outros; Philo, Mut. Nom. 110): capaz de discernir ou julgar, seguido de genitivo do objeto: <span class=\"greek\">κ</span>. <span class=\"greek\">ἐνθυμήσεων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐννοιῶν</span> <span class=\"greek\">καρδίας</span>, capaz de julgar os pensamentos e as deliberações do coração, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:12</a>.—DELG s.v. <span class=\"greek\">κρίνω</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0211-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κρόκος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κρόκος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (nome não muito comum; na forma grega, por exemplo OGI 140; CIG add. 4716d, 44; <span class=\"greek\">Κυπρ</span>. I p. 100 no. 74; PLond II, 257, 221; 223 p. 26 [94 d.C.]; BGU 90, 1; 537, 1): Croco, cristão efésio: <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἄξιος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὑμῶν</span>, digno de Deus e de vós, IEph 2:1. <span class=\"greek\">τὸ</span> <span class=\"greek\">ποθητόν</span> <span class=\"greek\">μοι</span> <span class=\"greek\">ὄνομα</span>, uma pessoa querida para mim, IRo 10:1.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0211-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κροκώδης, ες</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κροκώδης</span>, <span class=\"greek\">ες</span> (<span class=\"greek\">κρόκος</span>, ‘açafrão’, ±<span class=\"greek\">ώδης</span>, veja essa entrada [veja Schwyzer I 418]; Diod S 2, 52, 5; Diosc. 1, 27; Heraclides [KDeichgräber, D. griech. Empirikerschule 1930, 195, 22]; Aretaeus p. 58, 24): amarelo-açafrão, Hs 6, 1, 5.—DELG s.v. <span class=\"greek\">κρόκος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0211-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρούω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κρούω</span>: 1º aoristo <span class=\"greek\">ἔκρουσα</span> (desde Soph. e X., De Re Equ. 11, 4; PGM 5, 75; 92 e outros; LXX; TestSol; TestJob 6:4; TestJud 3:1 [<span class=\"greek\">αὐτόν</span>]; Philo, Mut. Nom. 139; Jos., Ant. 7, 306): dar um golpe contra alguma coisa, golpear, bater; em nossa literatura, somente bater à porta, usado absolutamente (sobre o contraste <span class=\"greek\">κρ</span>. … <span class=\"greek\">ἀνοίγω</span>, compare SSol 5:2 <span class=\"greek\">κρούει</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">θύραν</span> <span class=\"greek\">Ἄνοιξόν</span> <span class=\"greek\">μοι</span> e UPZ 79, 7 [159 a.C.] <span class=\"greek\">κρούει</span> <span class=\"greek\">θύραν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἀνοίγεται</span>; Eunap., Vi. Soph. p. 94, em sentido figurado de um sofista: <span class=\"greek\">ἔκρουε</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">θύραν</span> <span class=\"greek\">ἱκανῶς</span>, <span class=\"greek\">ἠνοίγετο</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">πολλάκις</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:7f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:9f</a>; 12:36; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:20</a>. Com acusativo <span class=\"greek\">τὴν</span> <span class=\"greek\">θύραν</span>, bater à porta (Aristoph., Eccles. 317; 990; X., Symp. 1, 11; Pla., Prot. 310a; 314d, Symp. 212c; PGM 4, 1854; TestJob 6:4. Outros exemplos do grego posterior em Field, Notes 120. Os aticistas rejeitam a expressão em favor de <span class=\"greek\">κόπτειν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θύραν</span> [Phryn. p. 177 Lob.]. <span class=\"greek\">κρ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">θύραν</span> Judg 19:22 A), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:13</a>. <span class=\"greek\">ἔκρουσεν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">θύραν</span>, bateu à porta, GJs 12:2 (<span class=\"greek\">ἔ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">θύραν</span>, variante de leitura; compare com <span class=\"greek\">ἐπί</span> Judg 19:22 B; SSol 5:2).—B. 553. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0211-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρύβω</h1><div class=\"entry-meta\"><span>verbo; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κρύβω</span>: veja <span class=\"greek\">κρύπτω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0211-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρύπτη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κρύπτη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (veja <span class=\"greek\">κρυπτός</span>, <span class=\"greek\">κρύπτω</span>; compare latim crypta; Callixenus: 627, Fgm. 1, 38 p. 163 ln. 22 Jac.; Strabo 17, 1, 37; Athen. 5, 205a; TestJob 46:5 <span class=\"greek\">κρυπτήν</span>; Jos., Bell. 5, 330 [Niese acentua <span class=\"greek\">κρυπτή</span>]; PSI 547, 18 [III a.C.]): lugar para esconder ou guardar alguma coisa, local escuro e oculto, porão ou adega: <span class=\"greek\">λύχνον</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τιθέναι</span>, colocar uma lâmpada num porão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:33</a> (variante de leitura <span class=\"greek\">κρυπτόν</span>).—Renehan ’75, 127. DELG s.v. <span class=\"greek\">κρύπτω</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0211-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρυπτός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo e substantivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κρυπτός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (veja <span class=\"greek\">κρύπτω</span>; Hom. e outros; papiros, LXX; TestReub 1:4; TestJud 12:5; JosAs 6:3 [também códice A 24:5 p. 76, 14 <span class=\"greek\">λόγος</span>]).</p>\n<p class=\"entry-text\">① Relativo ao que é desconhecido por ser mantido em segredo; oculto, secreto, como adjetivo (Herodian 5, 6, 3 <span class=\"greek\">κ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀόρατος</span>; SIG 973, 5f; BGU 316, 28; 3 Km 6:4; Ezk 40:16; 2 Macc 1:16; Jos., Ant. 15, 424; <span class=\"greek\">τὰ</span> <span class=\"greek\">κρυπτὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">φύσεως</span> <span class=\"greek\">μυστήρια</span>, os mistérios ocultos da natureza, Hippol., Ref. 1, 24, 2): <span class=\"greek\">ὁ</span> <span class=\"greek\">κρυπτὸς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">καρδίας</span> <span class=\"greek\">ἄνθρωπος</span>, o ser humano interior do coração, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:4</a> (veja <span class=\"greek\">ἄνθρωπος</span> 5a; compare Epict. 4, 11, 33). <span class=\"greek\">οὐδὲν</span> … <span class=\"greek\">κ</span>. <span class=\"greek\">ὸ̔</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">γνωσθήσεται</span>, nada há escondido que não se torne conhecido, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:2</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:22</a> (Philemon Com. 192 <span class=\"greek\">χρόνος</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">κρυπτὰ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">φάος</span> <span class=\"greek\">ἄγει</span>; JosAs 6:3 <span class=\"greek\">οὐδὲν</span> <span class=\"greek\">κρυπτὸν</span> <span class=\"greek\">λέληθεν</span> <span class=\"greek\">αὐτῷ</span>).</p>\n<p class=\"entry-text\">② Entidade oculta, algo escondido, substantivado, <span class=\"greek\">τὸ</span> <span class=\"greek\">κρυπτόν</span>. ⓐ Coisa oculta (Menand., Mon. 225 Mei. [316 J.]; Did., Gen. 171, 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:17</a>. Especialmente no plural <span class=\"greek\">τὰ</span> <span class=\"greek\">κρυπτά</span> (Dt 29:28; Is 29:10; Sus 42 Theod.; Jos., Bell. 5, 402; 413 <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">πάντα</span> <span class=\"greek\">ἐφορᾷ</span>): <span class=\"greek\">τὰ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐλέγχει</span>, põe em evidência as coisas secretas (assim, palavra por palavra, Artem. 1, 14 p. 19, 4 e 1, 44 p. 42, 8), IPhld 7:1. <span class=\"greek\">τὰ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τινος</span>, pensamentos, planos e propósitos secretos de alguém (Philemon Com. 233 <span class=\"greek\">φίλου</span>; Iambl., Myst. 6, 5 Partey; PGM 57, 13 <span class=\"greek\">τὰ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">θεᾶς</span> <span class=\"greek\">Ἴσιδος</span>; Sir 1:30; Jer 30:4), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:16</a>; IEph 15:3; IPhld 9:1. <span class=\"greek\">τὰ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">καρδίας</span> <span class=\"greek\">αὐτοῦ</span> (TestReub 1:4 <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">καρδίᾳ</span> <span class=\"greek\">μου</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">κ</span>.; compare Is 22:9 <span class=\"greek\">τὰ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">οἴκων</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἄκρας</span>), os pensamentos secretos do coração da pessoa (incrédula), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:25</a>; compare Pol 4:3. <span class=\"greek\">τὰ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">σκότους</span>, o que está oculto nas trevas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:5</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">αἰσχύνης</span>, as coisas escondidas por vergonha, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:2</a> (sobre o assunto, veja RKaster, The Shame of the Romans: TAPA 127, ’97, 1–19 [bibliografia]).</p>\n<p class=\"entry-text\">ⓑ Lugar oculto: <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κ</span>., em segredo (Vi. Aesopi W 104 P.; Orig., C. Cels. 8, 74, 4), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:4ab</a>, 6ab, 18, variante de leitura; <span class=\"greek\">ἐν</span> <span class=\"greek\">κ</span>., em lugar secreto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:4</a>; 18:20; em segredo, secretamente (TestJud 12:5; Orig., C. Cels. 7, 22, 31): <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">Ἰουδαῖος</span>, o judeu que o é interiormente, não apenas pelo sinal exterior da circuncisão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:29</a>; <span class=\"greek\">ἀνέβη</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κ</span>., subiu como que em particular, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:10</a>.—Sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:33</a>, variante de leitura, veja <span class=\"greek\">κρύπτη</span>.—DELG s.v. <span class=\"greek\">κρύπτω</span>. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0211-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρύπτω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κρύπτω</span> (veja <span class=\"greek\">κρυπτός</span>; desde Hom., com extensa variedade de sentidos, ‘esconder, ocultar, cobrir’; também <span class=\"greek\">κρύβω</span> [PGM 12, 322; ApcMos; Mel., P. 23, 155; Jos., Ant. 8, 410, C. Ap. 1, 292], do qual o imperfeito ativo <span class=\"greek\">ἔκρυβεν</span>, GJs 12:3, e o médio <span class=\"greek\">ἐκρυβόμην</span>, GPt 7:26, constitui formação nova do grego helenístico a partir do aoristo <span class=\"greek\">ἐκρύβην</span> [B-D-F §73; Mlt-H. 214; 245; Reinhold 72. Sobre a LXX, veja Helbing 83f]): futuro <span class=\"greek\">κρύψω</span> (LXX; GJs 14:1); 1º aoristo <span class=\"greek\">ἔκρυψα</span>. Na passiva: 2º futuro <span class=\"greek\">κρυβήσομαι</span> (PsSol 9:3; JosAs 6:3; ApcEsdr; Plut., Mor. 576d); 2º aoristo <span class=\"greek\">ἐκρύβην</span> (helenístico: Lob., Phryn. p. 317; LXX; JosAs 24:21; ApcMos 22 e outros; Jos., Ant. 8, 384); perfeito, 3ª pessoa do singular, <span class=\"greek\">κέκρυπται</span>; particípio <span class=\"greek\">κεκρυμμένος</span>.</p>\n<p class=\"entry-text\">① Impedir que algo seja visto, esconder. ⓐ De objetos e pessoas: dinheiro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:18</a> (compare o v. 25 em 2 abaixo); tesouro encontrado, 13:44b (compare o v. 44a em 2 abaixo). <span class=\"greek\">κ</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">προσώπου</span> <span class=\"greek\">τινός</span>, esconder alguém da presença de outra pessoa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:16</a>. Figuradamente, acerca da chave do conhecimento, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:52</a>, variante de leitura. Na passiva (Philo, Det. Pot. Ins. 128 <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀποκείμενα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σκότῳ</span> <span class=\"greek\">κέκρυπται</span>; Iren. 1, 18, 1 [Harv. I 171, 12]), de uma cidade sobre um monte: <span class=\"greek\">οὐ</span> <span class=\"greek\">δύναται</span> <span class=\"greek\">κρυβῆναι</span>, não pode ser escondida, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:14</a>; Ox 1 recto, 19f ([Logion 7] = ASyn. 53, ln. 22; veja GTh 32). De Moisés, que permaneceu sem ser descoberto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:23</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">μάννα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κεκρυμμένον</span>, o maná oculto, mantido fora da vista humana por estar guardado no céu, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:17</a>. Pertence aqui também o passivo <span class=\"greek\">κρυβῆναι</span> empregado com valor ativo, esconder-se (Gen 3:8, 10; Judg 9:5; 1 Km 13:6; 14:11; Job 24:4; 29:8; JosAs 6:3 e outros; ApcEsdr; ApcMos): <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">ἐκρύβη</span>, Jesus escondeu-se, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.59\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:59</a>. <span class=\"greek\">ἐκρύβη</span> <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">αὐτῶν</span>, escondeu-se deles, 12:36.—<span class=\"greek\">ποῦ</span> <span class=\"greek\">κρυβήσομαι</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">προσώπου</span> <span class=\"greek\">σου</span>;, onde me esconderei de tua presença?, 1 Cl 28:3.</p>\n<p class=\"entry-text\">ⓑ De estados ou condições: retirar da vista ou do conhecimento, esconder, guardar segredo (mandamentos délficos: SIG 1268 II, 16 [III a.C.] <span class=\"greek\">ἀπόρρητα</span> <span class=\"greek\">κρύπτε</span>; Just., D. 90, 2 <span class=\"greek\">τύποις</span> <span class=\"greek\">τὴν</span> … <span class=\"greek\">ἀλήθειαν</span>; Orig., C. Cels. 4, 39, 49): <span class=\"greek\">ἐὰν</span> <span class=\"greek\">αὐτῆς</span> <span class=\"greek\">κρύψω</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἁμάρτημα</span>, se eu encobrir o pecado (de Maria), GJs 14:1. <span class=\"greek\">τὶ</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span>, alguma coisa de alguém (Synes., Ep. 57 p. 195d; Gen 18:17; TestSol 5:10; TestBenj 2:6), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:25</a>. Na passiva, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:34</a>. Figuradamente, <span class=\"greek\">ἐκρύβη</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">ὀφθαλμῶν</span> <span class=\"greek\">σου</span>, ficou oculto a teus olhos, isto é, a ti, 19:42 (compare [<span class=\"greek\">τὰ</span>] <span class=\"greek\">βαθύτερα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">κεκρυμμένων</span> <span class=\"greek\">νοημάτων</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">γραφαῖς</span>, Orig., C. Cels. 7, 60, 34). Da conduta moral de uma pessoa: <span class=\"greek\">κρυβῆναι</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">δύνανται</span>, não pode ser escondida, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:25</a> (Diod S 14, 1, 3 <span class=\"greek\">ἀδυνατεῖ</span> <span class=\"greek\">κρύπτειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἄγνοιαν</span>; compare Ath., R. 19 p. 71, 30).—<span class=\"greek\">κεκρυμμένα</span>, coisas ocultas, desconhecidas (Philo, Spec. Leg. 3, 61; Tat. 13, 3 <span class=\"greek\">τὸ</span> <span class=\"greek\">κεκρυμμένον</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:35</a>. <span class=\"greek\">μαθητὴς</span> <span class=\"greek\">κεκρυμμένος</span>, discípulo secreto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.38\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:38</a> (<span class=\"greek\">τὸ</span> <span class=\"greek\">κεκρυμμένον</span> <span class=\"greek\">μυστήριον</span>, Hippol., Ref. 5, 8, 7).—Com o resultado de ocultar alguma coisa da vista (Hipponax [VI a.C.] 25 D. <span class=\"greek\">ἀσκέρηισι</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδας</span> <span class=\"greek\">δασείηισιν</span> <span class=\"greek\">ἔκρυψας</span>, colocaste meus pés em calçados forrados de pele): colocar (dentro), misturar (em), <span class=\"greek\">τὶ</span> <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span>, alguma coisa em outra coisa, (<span class=\"greek\">ζύμην</span>) <span class=\"greek\">γυνὴ</span> <span class=\"greek\">ἔκρυψεν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀλεύρου</span> <span class=\"greek\">σάτα</span> <span class=\"greek\">τρία</span>, uma mulher misturou (fermento) em três medidas de farinha, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:21</a>, variante de leitura (veja <span class=\"greek\">ἐγκρύπτω</span>).</p>\n<p class=\"entry-text\">ⓒ Fazer desaparecer, na passiva: <span class=\"greek\">ἵνα</span> <span class=\"greek\">ἀνομία</span> <span class=\"greek\">πολλῶν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">δικαίῳ</span> <span class=\"greek\">ἑνὶ</span> <span class=\"greek\">κρυβῇ</span>, para que a iniquidade de muitos desapareça em um só justo, Dg 9:5.</p>\n<p class=\"entry-text\">ⓓ Esconder em lugar seguro: <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">μάστιγος</span> <span class=\"greek\">γλώσσης</span> <span class=\"greek\">σε</span> <span class=\"greek\">κρύψει</span>, ele te esconderá do açoite da língua, 1 Cl 56:10 (Job 5:21). Na passiva (ParJer 9:6 <span class=\"greek\">ᾧ</span> <span class=\"greek\">πᾶσα</span> <span class=\"greek\">κτίσις</span> <span class=\"greek\">κέκρυπται</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span>): <span class=\"greek\">ἡ</span> <span class=\"greek\">ζωὴ</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">κέκρυπται</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Χριστῷ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>, vossa vida está escondida com Cristo em Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:3</a>.—Quando se menciona o lugar para onde pessoas ou coisas são levadas para escondê-las da vista, a palavra geralmente significa:</p>\n<p class=\"entry-text\">② Manter alguma coisa sem ser divulgada ou descoberta; ocultar, esconder, de algo posto em local determinado: <span class=\"greek\">κ</span>. <span class=\"greek\">τι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">γῇ</span>, esconder alguma coisa na terra (Apollon. Rhod. 4, 480 <span class=\"greek\">κρ</span>. <span class=\"greek\">τι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">γαίῃ</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:25</a> (compare o v. 18 em 1a acima); igualmente na passiva, <span class=\"greek\">θησαυρὸς</span> <span class=\"greek\">κεκρυμμένος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἀγρῷ</span>, tesouro escondido no campo, 13:44a (compare o v. 44b em 1a acima). Compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:24</a> D (compare <span class=\"greek\">ἡ</span> <span class=\"greek\">γῆ</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">κεκρυμμένη</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὑδάτων</span>, ‘terra completamente inundada’, Did., Gen. 31, 2). De pessoas vivas (Paus. 9, 19, 1): <span class=\"greek\">Ῥαὰβ</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">ἔκρυψεν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὑπερῷον</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">λινοκαλάμην</span>, Raabe escondeu-os no aposento superior, debaixo do linho, 1 Cl 12:3 (Diod S 4, 33, 9 <span class=\"greek\">κ</span>. <span class=\"greek\">εἰς</span>; Ps.-Apollod. 1, 4, 1, 4 [=p. 12 ln. 1] e escólio a Apollon. Rhod. 4, 532, 33 <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">γῆν</span> <span class=\"greek\">ἔκρυψε</span>).—<span class=\"greek\">κρύπτειν</span> <span class=\"greek\">ἑαυτόν</span>, esconder-se (En 10:2 <span class=\"greek\">κρύψον</span> <span class=\"greek\">σεαυτόν</span>; Nicander em Anton. Lib. 28, 3), <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span>, de alguém: (Maria) <span class=\"greek\">ἔκρυβεν</span> <span class=\"greek\">αὑτὴν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">υἱῶν</span> <span class=\"greek\">Ἰσραήλ</span>, (Maria) permaneceu escondida dos filhos de Israel, isto é, não aparecia em público, GJs 12:3 (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:24</a>). <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span>, dentro de alguma coisa: <span class=\"greek\">ἔκρυψαν</span> <span class=\"greek\">ἑαυτοὺς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">σπήλαια</span>, esconderam-se nas cavernas (Diod S 4, 12, 2 <span class=\"greek\">ἔκρυψεν</span> <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">πίθον</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:15</a>.—<span class=\"greek\">ἐκρυβόμεθα</span>, permanecíamos escondidos, GPt 7:26 (<span class=\"greek\">Δαυίδ</span> … <span class=\"greek\">ἐκρύβετο</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἀγρῷ</span>, Iren. 1, 18, 4 [Harv. I 175, 1]; Did., Gen. 92, 20).—B. 850. DELG. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0211-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρυσταλλίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κρυσταλλίζω</span> (veja o verbete seguinte; hápax legómenon): brilhar como cristal, ser tão transparente como cristal, a respeito do jaspe, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:11</a>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0211-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρύσταλλος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κρύσταλλος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">κρύος</span>, ‘geada’): cristal de rocha (assim Diod S 2, 52, 2; Strabo 15, 1, 67; Dio Chrys. 12 [13], 34; Aelian, NA 15, 8; Arrian, Anab. 3, 4, 4, a respeito de uma espécie de sal: <span class=\"greek\">καθαρὸς</span> <span class=\"greek\">ὥσπερ</span> <span class=\"greek\">κρύσταλλος</span>; Is 54:12; TestAbr A 12 p. 90, 22 [Stone p. 28]; ApcEsdr 5:23 p. 30, 27 Tdf.; EpArist 67; Philo, Somn. 1, 21), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:6</a> (compare PLond I, 130, 150 p. 137 [I/II d.C.] <span class=\"greek\">ὁμοία</span> <span class=\"greek\">κρυστάλλῳ</span>; Aëtius p. 4, 2 <span class=\"greek\">προσέοικε</span> <span class=\"greek\">κρυστάλλῳ</span>); 22:1. Ou seria provável preferir o sentido mais antigo, gelo (Hom.; Hdt.; Antig. Car. 144; Diod S 3, 34, 2; 17, 82, 5; Longus 3, 3, 2; Job 6:16; Wsd 16:22; Jos., Ant. 1, 30; TestLevi 3:2; SibOr 14, 151, Fgm. 1, 34), visto que <span class=\"greek\">κ</span>. é comparado a <span class=\"greek\">θάλασσα</span> e <span class=\"greek\">ποταμὸς</span> <span class=\"greek\">ὕδατος</span>, respectivamente mar e rio de água, nas duas passagens?—B. 69. DELG s.v. <span class=\"greek\">κρύος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0211-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρυφαῖος, αία, αῖον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κρυφαῖος</span>, <span class=\"greek\">αία</span>, <span class=\"greek\">αῖον</span> (veja os dois verbetes seguintes e <span class=\"greek\">κρύπτω</span>; Pind., Pla. e outros; LXX; TestAbr A 3 p. 80, 13 [Stone p. 8] [advérbio -<span class=\"greek\">αίως</span>]; JosAs 8:11, conjectura de MPhilonenko): relativo ao que se mantém fora do conhecimento geral, oculto, reservado; como descrição de Deus, <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κ</span>., não visto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:18a</a>; da capacidade de Deus de ver o que se passa no âmbito privado: <span class=\"greek\">ὁ</span> <span class=\"greek\">βλέπων</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κρυφαίῳ</span> <span class=\"greek\">ἀποδώσει</span> <span class=\"greek\">σοι</span>, aquele que vê o que se faz em segredo te recompensará, v. 18b (compare <span class=\"greek\">ἐν</span> <span class=\"greek\">κρυφαίοις</span>, Jer 23:24; La 3:10).—DELG s.v. <span class=\"greek\">κρύπτω</span> 6. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0211-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρυφῇ</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κρυφῇ</span> (veja o verbete precedente): advérbio (<span class=\"greek\">κρυφῆ</span>, Tdf.; veja W-S. §5, 11c; B-D-F §26 e 73; Mlt-H. 84.—Soph., X. e outros; óstraco: APF 6, 1920, 220 no. 8, 3 <span class=\"greek\">κρυφῆι</span> [III a.C.]; POxy 83, 14; LXX, Test12Patr, JosAs, ParJer): em segredo; <span class=\"greek\">τὰ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">γινόμενα</span> <span class=\"greek\">ὑπ</span>’ <span class=\"greek\">αὐτῶν</span>, as coisas que fazem em segredo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:12</a> (compare Lucian, Am. 21).—DELG s.v. <span class=\"greek\">κρύπτω</span> 5. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0211-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κρύφιος, ία, ιον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κρύφιος</span>, <span class=\"greek\">ία</span>, <span class=\"greek\">ιον</span> (veja os dois verbetes precedentes; Hes. e outros; LXX; PsSol 8:9): oculto, secreto; <span class=\"greek\">τὰ</span> <span class=\"greek\">κρύφια</span> <span class=\"greek\">ἔργα</span>, as obras ocultas, 2 Cl 16:3. Substantivado, <span class=\"greek\">τὰ</span> <span class=\"greek\">κ</span>., coisas escondidas ou secretas (LXX), 1 Cl 18:6 (Ps 50:8); B 6:10; IMg 3:2.—<span class=\"greek\">ἐν</span> <span class=\"greek\">κρυφίᾳ</span>, em segredo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:18</a> D.—DELG s.v. <span class=\"greek\">κρύπτω</span> 5.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0211-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κτάομαι</h1><div class=\"entry-meta\"><span>verbo médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κτάομαι</span>: futuro <span class=\"greek\">κτήσομαι</span>; 1º aoristo <span class=\"greek\">ἐκτησάμην</span>; perfeito <span class=\"greek\">κέκτημαι</span>; futuro perfeito, 3ª pessoa do singular, <span class=\"greek\">κεκτήσεται</span> (Tat. 20, 3, assim como Aeschyl., Th. 1022 e outros). Na passiva: futuro, 3ª pessoa do plural, <span class=\"greek\">κτηθήσοναι</span>, Jer 39:45 (veja o próximo verbete; desde Hom.).</p>\n<p class=\"entry-text\">① Ganhar posse de, conseguir para si, adquirir, obter; com <span class=\"greek\">τὶ</span>, alguma coisa, 2 Cl 5:7. <span class=\"greek\">πάντα</span> <span class=\"greek\">ὅσα</span> <span class=\"greek\">κτῶμαι</span>, toda a minha renda, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:12</a>. Seguido de acusativo e <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span>: <span class=\"greek\">χρυσὸν</span> … <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ζώνας</span>, adquirir ouro (para guardá-lo) nos cintos de dinheiro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:9</a>. Conseguir <span class=\"greek\">τὶ</span>, alguma coisa (Plut., Mor. 189d <span class=\"greek\">βιβλία</span> <span class=\"greek\">κτᾶσθαι</span>): <span class=\"greek\">τὴν</span> <span class=\"greek\">δωρεὰν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">χρημάτων</span> <span class=\"greek\">κτᾶσθαι</span>, obter mediante dinheiro o dom de Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:20</a> (Herodian 2, 6, 5 <span class=\"greek\">χρήμασι</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τι</span>). Também com <span class=\"greek\">ἐκ</span>: <span class=\"greek\">χωρίον</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">μισθοῦ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀδικίας</span>, adquirir um terreno com a recompensa da iniquidade, 1:18 (JSickenberger, BZ 18, ’29, 69–71). Também com genitivo de preço: <span class=\"greek\">πολλοῦ</span> <span class=\"greek\">κεφαλαίου</span>, por grande soma, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:28</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἑαυτοῦ</span> <span class=\"greek\">σκεῦος</span> <span class=\"greek\">κτᾶσθαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἁγιασμῷ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τιμῇ</span>, tomar uma esposa para si (ou: adquirir domínio sobre o próprio corpo; veja <span class=\"greek\">σκεῦος</span> 3) em santificação e honra, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:4</a> (compare <span class=\"greek\">κτᾶσθαι</span> <span class=\"greek\">γυναῖκα</span>, X., Symp. 2, 10; Sir 36:24). <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὑπομονῇ</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">κτήσεσθε</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ψυχὰς</span> <span class=\"greek\">ὑμῶν</span>, ganhareis vossas vidas por meio da perseverança, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:19</a>.</p>\n<p class=\"entry-text\">② Atrair sobre si, sobretudo desgraças e coisas semelhantes (Soph.; Eur.; Thu. 1, 42, 2 <span class=\"greek\">ἔχθραν</span>; Pr 3:31; ApcEsdr 2:12 p. 26, 5 Tdf. <span class=\"greek\">παρακοήν</span>): <span class=\"greek\">εὔχομαι</span>, <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μαρτύριον</span> <span class=\"greek\">αὐτὸ</span> <span class=\"greek\">κτήσωνται</span>, oro para que não tragam isso (minha mensagem) sobre si como testemunho (contra eles), IPhld 6:3.</p>\n<p class=\"entry-text\">③ Possuir; o perfeito (somente em Inácio em nossa literatura) tem esse sentido de presente (Appian, Bell. Civ. 5, 67 §282 <span class=\"greek\">οἱ</span> <span class=\"greek\">κεκτημένοι</span>, aqueles que possuíam [escravos]; En 97:10; TestSol 1:10 D; TestJob 11:2; JosAs 2:10 códice A; EpArist 229; Philo, Cher. 119, Mos. 1, 157 e outros; Jos., C. Ap. 1, 66; Just., D. 29, 2; Tat. 1:2 e outros): <span class=\"greek\">τινά</span>, alguém, <span class=\"greek\">ἐπίσκοπον</span>, bispo, IEph 1:3. <span class=\"greek\">τὶ</span>, algo: <span class=\"greek\">ὄνομα</span>, nome, 1:1; <span class=\"greek\">ἀγάπην</span>, amor, 14:2; <span class=\"greek\">λόγον</span> <span class=\"greek\">Ἰησοῦ</span>, palavra de Jesus, 15:2; <span class=\"greek\">πνεῦμα</span>, espírito, IMg 15; IPol 1:3; <span class=\"greek\">διακονίαν</span>, serviço ministerial, IPhld 1:1; <span class=\"greek\">γνώμην</span>, pensamento ou parecer, IPol 8:1.—M-M. DELG. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0211-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κτῆμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κτῆμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (veja o verbete precedente; desde Hom.).</p>\n<p class=\"entry-text\">① Aquilo que é adquirido ou possuído, em geral, de qualquer espécie (Menand., Dyscolus 156): <span class=\"greek\">πᾶν</span> <span class=\"greek\">κ</span>., todo bem, D 13:7. No plural, posses, propriedades (PRyl 28, 182; 76, 11; Jos., Ant. 14, 157): <span class=\"greek\">τὰ</span> <span class=\"greek\">κτήματα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">ὑπάρξεις</span>, os bens e as posses, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.45\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:45</a>. Ao lado de campos e casas, acerca de bens móveis, mobiliário, Hs 1:9. <span class=\"greek\">ἔχειν</span> <span class=\"greek\">κτ</span>. <span class=\"greek\">πολλά</span>, possuir muitos bens, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:22</a> (compare Diog., Ep. 38, 5, um jovem rico segue Diógenes <span class=\"greek\">διανείμας</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οὐσίαν</span>, depois de repartir seus bens. Porphyr., Vi. Plotini 7: Rogaciano, senador, desfaz-se de <span class=\"greek\">πᾶσα</span> <span class=\"greek\">κτῆσις</span>, todos os bens, e torna-se cínico).</p>\n<p class=\"entry-text\">② Propriedade fundiária, campo, porção de terra; no uso posterior, <span class=\"greek\">κ</span>. passou a restringir-se a esse sentido (desde Demosth. 18, 41; Menand., Dyscolus 40, 328, 737; Plut., Crass. 543 [1, 5]; Herodian 2, 6, 3; PTebt 5, 52; 120, 9; BGU 530, 21; Pr 23:10; 31:16; Philo, Spec. Leg. 2, 116; Jos., Bell. 4, 574), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:1</a> (=<span class=\"greek\">χωρίον</span>, v. 3).—B. 769. Renehan 75, 127. DELG s.v. <span class=\"greek\">κτάομαι</span> 4. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0211-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κτῆνος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κτῆνος</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span>: animal doméstico capaz de transportar cargas, animal domesticado, animal de estimação, animal de carga ou de montaria (sobretudo no plural, coletivamente ‘rebanhos, manadas’: desde os Hinos Homéricos e Hdt.; inscrições, papiros, LXX, TestSol, TestAbr, TestJob, Test12Patr, ApcMos; SibOr, Fgm. 3:12; EpArist, Philo, Mel.; Ath. 20, 4, R. 24 p. 78, 5; raramente no singular: X., An. 5, 2, 3; SIG 986, 8; Ex 22:4; TestAbr B 2 p. 106, 25 [Stone p. 60]; TestReub 2:9; Mel., P. 11, 93 <span class=\"greek\">παντὸς</span> <span class=\"greek\">κτήνους</span>, Theoph. Ant. 3, 9 [p. 224, 3]). Sobre animais de criação (PTebt 56, 8; LXX), Hv 4, 1, 5; Hs 9, 1, 8 (em contraste com animais selvagens e perigosos, 9, 1, 9; compare M. Ant. 5, 11 e Philo, Op. M. 64: <span class=\"greek\">κτ</span>. … <span class=\"greek\">θηρίον</span>); 9, 24, 1. Também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.39\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:39</a>; PtK 2 p. 14, 18 designam animais domesticados. Na combinação <span class=\"greek\">κτήνη</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πρόβατα</span>, gado e ovelhas, parece tratar-se somente de bovinos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:13</a> (compare PRyl 126, 15 <span class=\"greek\">τὰ</span> <span class=\"greek\">ἑατοῦ</span> <span class=\"greek\">πρόβατα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">βοικὰ</span> <span class=\"greek\">κτήνη</span>).—Sobre animais empregados para montaria (POxy 2153, 20 [III d.C.]; TestAbr, veja acima; Jos., Ant. 8, 241), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:24</a>.—DELG s.v. <span class=\"greek\">κτάομαι</span> 5. M-M. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0211-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κτήτωρ, ορος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κτήτωρ</span>, <span class=\"greek\">ορος</span>, <span class=\"greek\">ὁ</span> (Diod S 34 + 35, 2, 31; POxy 237 VIII, 31; 718, 13; PTebt 378, 24; entre outros [New Docs 2, 89]; Jo 1:11 Sym.): proprietário de casas e terras; <span class=\"greek\">χωρίων</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">οἰκιῶν</span>, de terrenos ou casas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:34</a> (compare 1QS 1:11f).—DELG s.v. <span class=\"greek\">κτάομαι</span> 7. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0211-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κτίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κτίζω</span> (veja os três verbetes seguintes): 1º aoristo <span class=\"greek\">ἔκτισα</span>; infinitivo perfeito <span class=\"greek\">ἐκτικέναι</span> (Just., D. 41, 1). Na passiva: futuro <span class=\"greek\">κτισθήσομαι</span>, LXX; 1º aoristo <span class=\"greek\">ἐκτίσθην</span>; perfeito <span class=\"greek\">ἔκτισμαι</span> (desde Hom.): trazer algo à existência, criar; em nossa literatura, acerca da atividade criadora de Deus (LXX, pseudoepígrafos; Eupolem. Hist. [II a.C.]: 723 Fgm. 2, 31 Jac. [em Eus., PE 9, 31]; Philo, Decal. 97; Jos., Bell. 3, 369; 379, Ant. 1, 27; Just.; SibOr 3, 20; IDefixWünsch 4, 1; PGM 5, 98ff): com <span class=\"greek\">τὶ</span>, alguma coisa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:3</a>; <span class=\"greek\">κτίσιν</span>, criação, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:19</a>; <span class=\"greek\">τὸν</span> <span class=\"greek\">οὐρανὸν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span>, o céu e o que nele existe, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 10:6</a>. <span class=\"greek\">δημιουργὸν</span> … <span class=\"greek\">ᾧ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">οὐρανοὺς</span> <span class=\"greek\">ἔκτισεν</span>, por meio de quem (Deus) criou os céus, Dg 7:2 (sobre o dativo, veja Kühner-G. §425, 7; compare Menand., Dyscolus 156). <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span>, todas as coisas (Herm. Wr. 13, 17), 4:11a; D 10:3; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:11b</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">κτίσας</span>, Deus, que criou todas as coisas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:9</a>; Hm 1:1; compare Hs 5, 5, 2. Na passiva, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:16ab</a> (compare <span class=\"greek\">ἐν</span> 4a). <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">κτίσας</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ὄντος</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὄντα</span>, Deus criou as coisas existentes a partir do que não existe, Hv 1, 1, 6 (compare Iren. 4, 38, 3 [Harv. II 295, 9]). <span class=\"greek\">τὸν</span> <span class=\"greek\">κόσμον</span>, o mundo, Hv 1, 3, 4. <span class=\"greek\">τὸν</span> <span class=\"greek\">κόσμον</span> <span class=\"greek\">ἕνεκα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀνθρώπου</span>, o mundo por causa do homem, m 12, 4, 2. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔθνη</span>, as nações, Hs 4:4. <span class=\"greek\">τὸν</span> <span class=\"greek\">λαόν</span>, o povo, Hs 5, 6, 2. <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκουμένην</span>, a terra habitada, 1 Cl 60:1 (compare Ps 88:12). Na passiva, <span class=\"greek\">ἐκτίσθη</span> <span class=\"greek\">ἀνήρ</span>, o homem foi criado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:9</a>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">κτισθέντων</span> … <span class=\"greek\">καλῶς</span> <span class=\"greek\">κτισθέντα</span>, dentre as coisas criadas por Deus, bem criadas, Dg 4:2. <span class=\"greek\">στοιχείων</span> … <span class=\"greek\">ἐκτισμένων</span>, dos elementos criados, 8:2. Sobre a comunidade cristã, representada como transcendente ao tempo: <span class=\"greek\">πάντων</span> <span class=\"greek\">πρώτη</span> <span class=\"greek\">ἐκτίσθη</span>, foi criada antes de todas as coisas, Hv 2, 4, 1; <span class=\"greek\">πρὸ</span> <span class=\"greek\">ἡλίου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σελήνης</span> <span class=\"greek\">ἐκτισμένης</span>, criada antes do sol e da lua, 2 Cl 14:1 (compare Ps 71:5). Dos anjos: <span class=\"greek\">οἱ</span> <span class=\"greek\">πρῶτοι</span> <span class=\"greek\">κτισθέντες</span>, os primeiros a serem criados, v 3, 4, 1; Hs 5, 5, 3. Absolutamente, <span class=\"greek\">ὁ</span> <span class=\"greek\">κτίσας</span>, o Criador (Jos., Bell. 3, 354), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:4</a> (variante de leitura <span class=\"greek\">ποιήσας</span>). <span class=\"greek\">ὁ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">κτίσας</span>, aquele que criou todas as coisas, Hs 7:4 (PGM 13, 62 <span class=\"greek\">τὸν</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">κτίσαντα</span>; 983).—Também do Espírito: <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κτίσαν</span> <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κτίσιν</span>, o Espírito que criou toda a criação, Hs 5, 6, 5.—Da atividade criadora divina em relação à vida interior: de pessoas que foram <span class=\"greek\">κτισθέντες</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Χριστῷ</span> <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ἔργοις</span> <span class=\"greek\">ἀγαθοῖς</span>, criadas (por Deus) em Cristo Jesus para boas obras, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:10</a>. Com referência a Gen 1:26f: <span class=\"greek\">ἵνα</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">δύο</span> <span class=\"greek\">κτίσῃ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἕνα</span> <span class=\"greek\">καινὸν</span> <span class=\"greek\">ἄνθρωπον</span>, para que ele (Cristo) criasse os dois (israelitas e não israelitas) nele como um único ser humano novo (ou uma nova humanidade), v. 15; <span class=\"greek\">τὸν</span> <span class=\"greek\">καινὸν</span> <span class=\"greek\">ἄνθρωπον</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">κτισθέντα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">δικαιοσύνῃ</span>, o novo ser humano, criado à semelhança de Deus em justiça, 4:24. Correspondentemente, <span class=\"greek\">τὸν</span> <span class=\"greek\">νέον</span> (<span class=\"greek\">ἄνθρωπον</span>) <span class=\"greek\">τὸν</span> <span class=\"greek\">ἀνακαινούμενον</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἐπίγνωσιν</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">εἰκόνα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κτίσαντος</span> <span class=\"greek\">αὐτόν</span>, o novo ser humano, renovado no conhecimento segundo a imagem daquele que o criou, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:10</a>. <span class=\"greek\">ἐγενόμεθα</span> <span class=\"greek\">καινοί</span>, <span class=\"greek\">πάλιν</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἀρχῆς</span> <span class=\"greek\">κτιζόμενοι</span>, tornamo-nos novos, sendo novamente criados desde o princípio, B 16:8. <span class=\"greek\">καρδίαν</span> <span class=\"greek\">καθαρὰν</span> <span class=\"greek\">κτίσον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐμοί</span>, cria em mim um coração puro, 1 Cl 18:10 (Ps 50:12). <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κτίσαντι</span> <span class=\"greek\">ἡμᾶς</span>, a Deus que nos criou, 2 Cl 15:2. Figuradamente, <span class=\"greek\">ὁ</span> … <span class=\"greek\">κτίσας</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">δένδρον</span> <span class=\"greek\">τοῦτο</span>, aquele que criou esta árvore, Hs 8, 2, 9 (compare 8, 3, 2). Veja sobre <span class=\"greek\">ἐκλογή</span>, final, e Teschendorf sob <span class=\"greek\">γίνομαι</span> 2a.—PKatz, The mng. of the root <span class=\"hebrew\" dir=\"rtl\">קנה</span>: JJS 5, ’54, 126–31.—DELG. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0211-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κτίσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κτίσις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (veja o verbete precedente e os dois seguintes; desde Pind.).</p>\n<p class=\"entry-text\">① Ato de criar, criação (Iren. 1, 17, 1 [Harv. I 164, 11]; Hippol., Ref. 6, 33 <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span>; 6, 55, 1; Did., Gen. 24, 4): <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">κτίσεως</span> <span class=\"greek\">κόσμου</span>, desde a criação do mundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:20</a> (compare PsSol 8, 7; ApcSed 8:10; Jos., Bell. 4, 533). O Filho de Deus foi <span class=\"greek\">σύμβουλος</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πατρὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κτίσεως</span> <span class=\"greek\">αὐτοῦ</span>, conselheiro do Pai em sua obra criadora, Hs 9, 12, 2.</p>\n<p class=\"entry-text\">② Resultado de um ato criador, aquilo que é criado (EpArist 136; 139; TestReub 2:9).</p>\n<p class=\"entry-text\">ⓐ Coisas ou seres criados individualmente, criatura (Tob 8:5, 15), coisa criada: <span class=\"greek\">τὶς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἑτέρα</span>, qualquer outra criatura, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.39\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:39</a>. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστιν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἀφανὴς</span> <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">αὐτοῦ</span>, nenhuma criatura está oculta à vista de Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:13</a>. <span class=\"greek\">πᾶν</span> <span class=\"greek\">γένος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span>, toda espécie de criatura que o Senhor fez, Hs 9, 1, 8; <span class=\"greek\">πᾶσα</span> <span class=\"greek\">κ</span>., cada criatura (compare Jdth 9:12), MPol 14:1. Sobre Cristo: <span class=\"greek\">πρωτότοκος</span> <span class=\"greek\">πάσης</span> <span class=\"greek\">κ</span>., primogênito de toda a criação, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:15</a>. Sobre o nome de Deus: <span class=\"greek\">ἀρχέγονον</span> <span class=\"greek\">πάσης</span> <span class=\"greek\">κ</span>., anterior a toda a criação, 1 Cl 59:3. <span class=\"greek\">τὸ</span> <span class=\"greek\">εὐαγγέλιον</span> … <span class=\"greek\">τὸ</span> <span class=\"greek\">κηρυχθὲν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πάσῃ</span> <span class=\"greek\">κτίσει</span>, o evangelho anunciado a toda criatura (aqui limitado aos seres humanos), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:23</a>.—No plural (En 18:1): <span class=\"greek\">δοξάζειν</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">κτίσεις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, louvar as obras criadas por Deus, Hv 1, 1, 3.—O cristão é descrito por Paulo como <span class=\"greek\">καινὴ</span> <span class=\"greek\">κ</span>., nova criatura, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:17</a>, e o estado de pertencer à nova fé é expresso pelas mesmas palavras como nova criação, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:15</a> (compare Jos., Ant. 18, 373 <span class=\"greek\">καιναὶ</span> <span class=\"greek\">κτίσεις</span>). Veja sobre <span class=\"greek\">ἐκλογή</span>, final.</p>\n<p class=\"entry-text\">ⓑ A totalidade de tudo o que foi criado; criação, mundo (ApcMos 32; SibOr 5, 152; <span class=\"greek\">ὁρωμένη</span> <span class=\"greek\">κ</span>., criação visível, Did., Gen. 1 B, 6; 13 A, 2): <span class=\"greek\">ἡ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">αὐτοῦ</span>, sua criação, Hv 1, 3, 4. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀρχῇ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κ</span>., no princípio do mundo, B 15:3; <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">ἀρχῆς</span> <span class=\"greek\">κ</span>., desde o princípio do mundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:4</a>. Igualmente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:6</a>; <span class=\"greek\">πᾶσα</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">κ</span>., toda a criação (Jdth 16:14; Ps 104:21, variante de leitura; TestAbr A 13 p. 92, 7 [Stone p. 32], B 12 p. 116, 31 [St. p. 80]; TestLevi 4:1; TestNapht 2:3; ParJer 9:6; PGM 12, 85), Hv 3, 4, 1; m 12, 4, 2; Hs 5, 6, 5; 9, 14, 5; 9, 23, 4; 9, 25, 1. O mundo inteiro está cheio da glória de Deus, 1 Cl 34:6. <span class=\"greek\">ἀόργητος</span> <span class=\"greek\">ὑπάρχει</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κτίσιν</span> <span class=\"greek\">αὐτοῦ</span>, é sem ira para com toda a sua criação, 19:3. <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span> <span class=\"greek\">πάσης</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κτίσεως</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">προγενέστερός</span> <span class=\"greek\">ἐστιν</span>, o Filho de Deus é mais antigo que toda a sua criação, Hs 9, 12, 2. <span class=\"greek\">πᾶσα</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">κ</span>., toda a criação, limitada à humanidade, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:15</a>; Hm 7:5. Também <span class=\"greek\">ἡ</span> <span class=\"greek\">κτίσις</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνθρώπων</span>, a criação dos seres humanos, D 16:5.—<span class=\"greek\">αὕτη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">κ</span>., este mundo (terrestre, em contraste com o celestial), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:11</a>.—<span class=\"greek\">κ</span>., a criação, aquilo que foi criado, em oposição ao Criador (Wsd 16:24), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:25</a> (EpArist 139 <span class=\"greek\">θεὸν</span> <span class=\"greek\">σεβόμενοι</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ὅλην</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κτίσιν</span>).—De Cristo: <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀρχὴ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κτίσεως</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, o princípio da criação de Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:14</a> (veja <span class=\"greek\">ἀρχή</span> 3).—O sentido de <span class=\"greek\">κτ</span>. é controvertido em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:19</a>–22, embora a passagem seja geralmente entendida como a expectativa de toda a criação inferior ao nível humano (animada e inanimada — assim, por exemplo, OCullmann, Christ and Time [tradução de FFilson] ’50, 103).—HBiedermann, D. Erlösg. der Schöpfung beim Ap. Pls. ’40.</p>\n<p class=\"entry-text\">③ Sistema de autoridade estabelecida resultante de um ato de fundação, sistema de governo, sistema de autoridade. Em correspondência com 1, <span class=\"greek\">κτίσις</span> também é o ato pelo qual se cria um organismo de governo ou uma entidade dotada de autoridade (inscrição em CB I/2, 468 no. 305 [I d.C.]: fundação da Gerousia [Senado]. Algo comparável à fundação de uma cidade: Scymnus Chius v. 89 <span class=\"greek\">κτίσεις</span> <span class=\"greek\">πόλεων</span>). Mas, conforme 2, também é provavelmente o resultado do ato, a instituição ou autoridade propriamente dita, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:13</a> (Diod S 11, 60, 2 apresenta <span class=\"greek\">κτίστης</span> como título de alto funcionário. Compare <span class=\"greek\">νομοθεσία</span> em ambos os sentidos: 1. ato de dar leis, legislação; 2. resultado do ato, isto é, lei). Para um heleno, era fundamental uma sociedade bem ordenada (veja Aristot., Pol. 1, 1, 1, 1252). Entendia-se que a função do governo consistia em manter tal sociedade, e o objetivo moral descrito no v. 14 corresponde a essa finalidade.—BBrinkman, ‘Creation’ and ‘Creature’ I, Bijdragen (Nijmegen) 18, ’57, 129–39, também 359–74; GLampe, The NT Doctrine of <span class=\"greek\">κτίσις</span>, SJT 17, ’64, 449–62.—DELG s.v. <span class=\"greek\">κτίζω</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0211-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κτίσμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κτίσμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (veja os dois verbetes precedentes e o seguinte; Polyb. 4, 70, 3; Dionys. Hal. 1, 59; Strabo 7, 5, 5; Vett. Val. 213, 6; SIG 799, 7 [38 d.C.]; PGM 7, 483; BGU 3, 19; LXX, pseudoepígrafos; Just.; Iren. 1, 5, 4 [Harv. I 48, 2], na especulação gnóstica; empréstimo no hebraico rabínico): em nossa literatura, sempre (como Wsd 9:2; 13:5; 14:11; Sir 36:14; 38:34; 3 Macc 5:11; EpArist 17; Iren. 1, 10, 2 [Harv. I 93, 3]; Did., Gen. 220, 28) resultado da atividade criadora, aquilo que é criado (por Deus), criatura (criada por Deus): <span class=\"greek\">πᾶν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">θεοῦ</span> <span class=\"greek\">καλόν</span>, tudo o que Deus criou é bom, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:4</a>. <span class=\"greek\">πᾶν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ὅ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">οὐρανῷ</span>, toda criatura que está no céu, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:13</a>.—No plural, componentes da criação (TestAbr B 7 p. 12, 8 [Stone p. 72] <span class=\"greek\">τὰ</span> <span class=\"greek\">κτίσματα</span> <span class=\"greek\">ἃ</span> <span class=\"greek\">ἐκτίσατο</span> … <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span>; TestJob 47:11; Herm. Wr. 1, 18 <span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">κ</span>.; Sextus 439; Orig., C. Cels. 7, 46, 39; Did., Gen. 109, 25), Dg 8:3.—<span class=\"greek\">τὰ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">θαλάσσῃ</span>, as criaturas que estão no mar, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 8:9</a>.—<span class=\"greek\">τὰ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, aquilo que Deus criou, Hv 3, 9, 2; m 8:1; a humanidade é senhora disso, 12, 4, 3. Os cristãos são <span class=\"greek\">ἀπαρχή</span> <span class=\"greek\">τις</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">κ</span>., uma espécie de primícias das criaturas de Deus (aqui <span class=\"greek\">κ</span>. refere-se sobretudo a seres humanos; para uma restrição semelhante no emprego de <span class=\"greek\">κτίσις</span>, veja esse verbete 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:18</a>.—DELG s.v. <span class=\"greek\">κτίζω</span>. M-M. TW. Sv.</p></section></article>"};
